def build_n3_entries():
    entries = []
    for suffix, pattern, romaji, meaning, formation, usage_notes, similar, sentence_examples in N3_GRAMMAR_ENTRIES:
        entries.append({
            "id": f"bunpou_{suffix}",
            "pattern": pattern,
            "patternRomaji": romaji,
            "jlptLevel": "N3",
            "meaning": meaning,
            "formation": formation,
            "usageNotes": usage_notes,
            "similarPatterns": [f"bunpou_{s}" for s in similar],
            "sentenceExamples": [
                {"japanese": jp, "romaji": ro, "translation": tr}
                for jp, ro, tr in sentence_examples
            ],
        })
    return entries


def build_placeholder_entries():
    entries = []
    for level, count in PLACEHOLDER_COUNTS.items():
        for i in range(1, count + 1):
            entries.append({
                "id": f"bunpou_{level.lower()}_placeholder_{i}",
                "pattern": "",
                "patternRomaji": "",
                "jlptLevel": level,
                "meaning": "",
                "formation": "",
                "usageNotes": "",
                "similarPatterns": [],
                "sentenceExamples": [],
                "placeholder": True,
            })
    return entries


def main():
    data = (
        build_n5_entries() + build_n4_entries() + build_n3_entries()
        + build_placeholder_entries()
    )
    with open("assets/data/bunpou_data.json", "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"Wrote {len(data)} bunpou entries ({len(N5_GRAMMAR_ENTRIES)} real N5 (of "
          f"{len(N5_GRAMMAR)} locked) + {len(N4_GRAMMAR_ENTRIES)} real N4 (of "
          f"{len(N4_GRAMMAR)} locked) + {len(N3_GRAMMAR_ENTRIES)} real N3 (of "
          f"{len(N3_GRAMMAR)} locked) + {sum(PLACEHOLDER_COUNTS.values())} placeholders).")


if __name__ == "__main__":
    main()
